-- 보유도서 테이블 (도서/위치/상태 반정규화 통합, book_held_id는 UUID, book_id는 원본 도서 식별자 반정규화)
;

-- 회원 테이블 (회원등급 반정규화 통합, 대출정지/예약제한 현재 상태 포함)
;

-- 대출 테이블 (연체/변상 이력 반정규화 통합)
;

-- loan_id identity 시퀀스를 다음 값으로 맞춤 (명시적으로 PK를 입력했으므로 필요)
SELECT setval(pg_get_serial_sequence('tbl_loan_1', 'loan_id'), (SELECT MAX(loan_id) FROM tbl_loan_1) + 1, false);

-- 예약 테이블 (예약상태 반정규화 통합)
;

SELECT setval(pg_get_serial_sequence('tbl_reservation_1', 'reservation_id'), (SELECT MAX(reservation_id) FROM tbl_reservation_1) + 1, false);

-- 제한이력 테이블 (대출정지 테이블 + 예약제한 테이블 통합, 대출정지상태 반정규화 통합 / L:대출정지, R:예약제한)
;

SELECT setval(pg_get_serial_sequence('tbl_restriction_1', 'restriction_id'), (SELECT MAX(restriction_id) FROM tbl_restriction_1) + 1, false);
